 private static void voiceAndList()throws Exception{
  World w=new World();w.program(string(0x35,"SYSTEM"));Pc1Fetch.Dispatch d=w.dispatcher.next(w.frame);w.frame.writeByte(Pc1Fetch.Frame.BUFFER,'C');Pc1RawDispatch.Result r=w.dispatcher.execute(w.frame,d);check(r.loop&&w.output.names.equals(Arrays.asList("CYSTEM")),"35 reads live raw Frame source after fetch: loop="+r.loop+",names="+w.output.names+",calls="+w.output.calls+",voice="+w.g(0x454d10)+",ready="+w.g(0xbc1d10));check(w.output.calls.contains("play:2:0")&&w.output.runtimeBlocked&&w.output.renderBlocked&&w.output.handlerBlocked,"Actual Audio tail and all snapshot boundaries reached");w.step();w.handlers.requireBoundary();
  World stop=new World();stop.program(string(0x35,"--"));stop.g(0xbbab04,1);stop.step();check(stop.output.calls.equals(Arrays.asList("stop:2")),"Mutable raw stop literal routes41CBE0 without name load");
  World list=new World();list.program(string(0x47,"SYSTEM"),string(0x47,"GAYA"),shortOp(0x24,1,0),shortOp(0x24,2,0));list.step();list.step();check(list.g(0xbb84bc)==2&&list.name(0x9b96e4).equals("SYSTEM")&&list.name(0x9b9764).equals("GAYA"),"47 copies actual voice-list bytes with native stride/count");list.step();check(list.output.names.equals(Arrays.asList("SYSTEM","GAYA"))&&list.output.calls.contains("play:3:0")&&list.output.calls.contains("play:4:0")&&list.g(Pc1Fetch.ARGUMENT1)==2,"24 mode1 loads then starts requested mixed channels in actual loop");list.step();check(list.g(0xbb84bc)==0&&list.name(0x9b96e4).equals("SYSTEM"),"24 clear preserves inactive raw names");
  World rand=new World();rand.program(string(0x47,"SYSTEM"),shortOp(0x24,0,0),shortOp(0x23,7,0));rand.step();rand.step();check(rand.output.names.equals(Arrays.asList("SYSTEM"))&&rand.g(Pc1Fetch.ARGUMENT1)==0,"24 random single voice uses real CRT state and live list");rand.step();check(rand.g(0xbb8428)>=0&&rand.g(0xbb8428)<7,"23 publishes real signed remainder");
 }
 private static void musicAndSound()throws Exception{
  World bgm=new World();bgm.program(shortOp(6,0,0));Pc1Fetch.Dispatch d=bgm.dispatcher.next(bgm.frame);bgm.g(Pc1Fetch.ARGUMENT0,99);bgm.output.onLoad=()->bgm.g(Pc1Fetch.ARGUMENT0,7);bgm.g(0x94c6ac,1);bgm.output.onTimer=()->bgm.g(Pc1Fetch.ARGUMENT0,8);bgm.dispatcher.execute(bgm.frame,d);check(bgm.output.names.equals(Arrays.asList("bgm"))&&bgm.audio.currentTrack()==0,"06 uses cached EDX track through real catalog/audio");check(bgm.g(0x9d8a0c)==8&&bgm.output.calls.contains("timer:150"),"06 reloads global ARG0 after actual request/timer callbacks");
  World selected=new World();selected.program(shortOp(6,254,2));selected.g(0x968a00,0);selected.step();check(selected.audio.scriptMode()==1&&selected.g(0x9d8a0c)==0&&selected.output.calls.contains("play:0:0"),"06 FE selection and mode2 loop policy share canonical controls");
  World same=new World();same.program(shortOp(6,0,1));same.g(0x9d8a0c,0);same.g(0xbb8438,5);same.g(0x94c6ac,1);same.step();check(same.output.names.isEmpty()&&same.audio.scriptMode()==5&&same.output.calls.contains("timer:150"),"06 mode1 same logical music skips request only, still arms timer");
  World end=new World();end.program(shortOp(6,255,0));end.g(0x94c6ac,1);end.step();check(end.g(0x9d8a0c)==-1&&end.output.calls.stream().noneMatch(x->x.startsWith("timer")),"06 FF immediate stop bypasses timer and common request publication");
  World sound=new World();sound.program(shortOp(5,0,1));sound.output.onLoad=()->{sound.g(Pc1Fetch.ARGUMENT0,9);sound.g(Pc1Fetch.ARGUMENT1,2);};sound.step();check(sound.output.calls.contains("play:1:1")&&sound.g(0x9d8a10)==0x209,"05 uses cached request but late packed arguments after audio callback");
  World fade=new World();fade.program(shortOp(5,255,1));fade.g(0xbbab00,1);fade.step();check(fade.output.calls.contains("timer:10")&&fade.g(0x9d8a10)==0,"05 FF/1 requests real sound fade and timer");
 }
 private static void pending(boolean interrupted)throws Exception{
  World w=new World();w.fixture.backend.images.put("bg",Pc1GraphicsResources.Source.rgb(Pc1RenderContextTests.solid(64,48,0x334455)));w.graphics.render().path(0,new byte[]{'b','g'});w.program(string(0x35,"SYSTEM"));Pc1Fetch.Dispatch d=w.dispatcher.next(w.frame);w.fixture.record(0,1,2,64,0,0,0,4,5);w.g(0x9b9f18,1);w.g(0xbb844c,2);w.interrupt=interrupted;Pc1RawDispatch.Result r=w.dispatcher.execute(w.frame,d);
  NativeRgbImage baked=Pc1RenderContextTests.solid(64,48,0x334455);for(int y=2;y<7;y++)for(int x=1;x<5;x++)baked.setRgb(x,y,0);check(w.g(0x9b9f18)==0&&w.g(Pc1Compositor.PENDING_BAKED)==1&&Arrays.equals(baked.bgr24(),w.graphics.render().compositor().rgb(w.g(0x43d418)).bgr24()),"35 pending path performs actual bake pixels on canonical background");
  if(interrupted){check(!r.loop&&r.nativeResult()==1&&w.output.names.isEmpty()&&w.g(0xbb844c)==2&&w.g(Pc1Fetch.LAST_OPCODE)==-1,"Interrupted complete transition consumer returns1 without tail/visibility clear/voice");check(w.pumps==1&&w.g(Pc1Transition.BUSY)==1&&!Arrays.equals(baked.bgr24(),w.graphics.render().compositor().front().bgr24()),"Interruption preserves actual transition prefix and partial pixels, no fake cleanup");}
  else check(r.loop&&w.output.names.equals(Arrays.asList("SYSTEM"))&&w.g(0xbb844c)==0&&w.pumps>0&&w.g(Pc1Transition.BUSY)==0&&Arrays.equals(baked.bgr24(),w.graphics.render().compositor().front().bgr24()),"Actual complete41A0B0 finishes exact pixels/pump before voice");
 }
